"""Styled, formula-safe XLSX snapshots generated by the Python app at runtime."""

from io import BytesIO
import json
import math
from numbers import Real
import re

import pandas as pd
import xlsxwriter
from .i18n import TEXT


def excel_bytes(tables, manifest, lang="English", labels=None):
    """Preserve table values and provenance; never interpret user strings as formulas."""
    ru = lang == "Русский"
    labels = {**TEXT, "scenario": ("Scenario", "Сценарий"), **(labels or {})}
    output = BytesIO()
    book = xlsxwriter.Workbook(output, {"in_memory": True, "strings_to_formulas": False, "strings_to_urls": False})
    book.set_properties({"title": "BUSINESS LAB PRO", "comments": "Model snapshot; not audited actuals."})
    title = book.add_format({"bold": True, "font_size": 22, "font_color": "#FFFFFF", "bg_color": "#143D46"})
    note = book.add_format({"font_color": "#52656B", "text_wrap": True, "valign": "top", "font_size": 10})
    header = book.add_format(
        {"bold": True, "font_color": "#FFFFFF", "bg_color": "#237A83", "text_wrap": True, "valign": "vcenter"}
    )
    text = book.add_format({"font_name": "Calibri", "font_size": 11, "valign": "top", "text_wrap": True})
    number = book.add_format({"num_format": '#,##0.00;[Red](#,##0.00);"—"', "valign": "top"})
    integer = book.add_format({"num_format": '#,##0;[Red](#,##0);"—"', "valign": "top"})
    percent = book.add_format({"num_format": '0.0%;[Red](0.0%);"—"', "valign": "top"})
    negative = book.add_format({"font_color": "#A52E3E", "bg_color": "#FCECEF"})
    names = set()
    tab_labels = {
        "scenarios": "Сценарии",
        "inputs": "Параметры",
        "forecast_default": "Прогноз (допущения)",
        "decision_journal": "Журнал решений",
        "marketing_inputs": "Данные маркетинга",
        "marketing_kpis": "KPI маркетинга",
    }
    fraction_columns = {
        "returns",
        "discount",
        "payment_rate",
        "conversion",
        "ctr",
        "margin",
        "contribution_margin",
        "profit_margin",
        "revenue_variance_rate",
        "visitor_to_lead",
        "lead_to_customer",
        "operating_margin",
        "gross_margin",
        "repeat_rate",
        "return_rate",
        "conversion_rate",
    }
    count_columns = {
        "orders",
        "units",
        "month",
        "months",
        "clicks",
        "impressions",
        "leads",
        "customers",
        "new_customers",
        "paid_new",
        "id",
    }

    def sheet(name, subtitle):
        base = re.sub(r"[\[\]:*?/\\]", " ", name).strip().strip("'")[:31] or "Data"
        unique, suffix = base, 1
        while unique.casefold() in names:
            suffix += 1
            unique = base[:26] + f" ({suffix})"
        names.add(unique.casefold())
        ws = book.add_worksheet(unique)
        ws.hide_gridlines(2)
        ws.set_tab_color("#237A83")
        ws.merge_range(0, 0, 0, 5, "BUSINESS LAB PRO", title)
        ws.set_row(0, 40)
        ws.merge_range(1, 0, 1, 5, subtitle, note)
        ws.set_row(1, 32)
        ws.set_landscape()
        ws.fit_to_pages(1, 0)
        ws.set_paper(9)
        ws.set_margins(0.3, 0.3, 0.5, 0.5)
        ws.set_footer("&LBUSINESS LAB PRO&R&P / &N")
        return ws

    scenarios = tables.get("scenarios.csv")
    if (
        scenarios is not None
        and not scenarios.empty
        and {"scenario", "currency", "revenue"}.issubset(scenarios.columns)
    ):
        ws = sheet(
            "Обзор" if ru else "Overview",
            "Ключевые показатели · снимок расчётов" if ru else "Key metrics · calculation snapshot",
        )
        ws.set_column(0, 0, 42)
        ws.set_column(1, max(5, len(scenarios)), 25)
        ws.write(4, 0, "Показатель" if ru else "Metric", header)
        for col, (_, scenario) in enumerate(scenarios.iterrows(), 1):
            ws.write_string(4, col, f"{scenario['scenario']} · {scenario['currency']}", header)
        ws.set_row(4, 44)
        metrics = [
            "revenue",
            "gross_profit",
            "contribution_profit",
            "operating_profit",
            "contribution_margin",
            "profit_margin",
            "marketing_spend",
            "break_even_revenue",
        ]
        for row, metric in enumerate(metrics, 5):
            ws.write_string(row, 0, labels[metric][int(ru)], text)
            for col, (_, scenario) in enumerate(scenarios.iterrows(), 1):
                fmt = percent if metric in fraction_columns else number
                value = scenario.get(metric)
                if value is None or pd.isna(value):
                    ws.write_blank(row, col, None, fmt)
                else:
                    ws.write_number(row, col, value, fmt)
            ws.set_row(row, 30)
        ws.conditional_format(
            5, 1, 12, len(scenarios), {"type": "cell", "criteria": "<", "value": 0, "format": negative}
        )
        ws.merge_range(
            15,
            0,
            15,
            5,
            "Источник: текущая модель и сохранённые сценарии. Валюта каждого сценария сохранена; курсы не применяются. Расчёты не являются подтверждёнными фактическими данными."
            if ru
            else "Source: current model and saved scenarios. Each scenario retains its currency; no FX conversion. Calculated values are not audited actuals.",
            note,
        )
        ws.set_row(15, 48)
        ws.freeze_panes(5, 1)
        ws.print_area(0, 0, 15, max(5, len(scenarios)))
    for name, frame in tables.items():
        key = name.removesuffix(".csv")
        caption = tab_labels.get(key, key.replace("_", " ").title()) if ru else key.replace("_", " ").title()
        ws = sheet(caption, caption + (" · Снимок данных модели" if ru else " · Model data snapshot"))
        ws.merge_range(
            2,
            0,
            2,
            5,
            "Валюта указана в строках. Пусто = нет результата. Суммы без конвертации."
            if ru
            else "Currency is recorded per row. Blank = undefined. No currency conversion.",
            note,
        )
        ws.set_row(2, 30)
        if frame.empty or len(frame.columns) == 0:
            ws.write(4, 0, "Нет данных" if ru else "No data", note)
            ws.set_column(0, 5, 20)
            continue
        if len(frame) > 1_048_571 or len(frame.columns) > 16_384:
            raise ValueError("Table exceeds Excel worksheet limits")
        columns = []
        used_headers = set()
        for col, column in enumerate(frame.columns):
            key_col = str(column)
            display = labels.get(key_col, (key_col.replace("_", " ").title(),) * 2)[int(ru)]
            if display.casefold() in used_headers:
                display += f" ({col + 1})"
            used_headers.add(display.casefold())
            fmt = percent if key_col in fraction_columns else integer if key_col in count_columns else number
            if not pd.api.types.is_numeric_dtype(frame[column].dtype):
                fmt = text
            columns.append({"header": display, "header_format": header, "format": fmt})
            width = min(
                38,
                max(
                    18, len(display) * 0.9 + 3, min(32, max((len(str(v)) for v in frame[column].head(100)), default=0))
                ),
            )
            ws.set_column(col, col, width, fmt)
        ws.add_table(4, 0, 4 + len(frame), len(columns) - 1, {"style": "Table Style Medium 2", "columns": columns})
        ws.set_row(4, 46)
        for row_index, row in enumerate(frame.itertuples(index=False, name=None), 5):
            height = 22
            for col, value in enumerate(row):
                fmt = columns[col]["format"]
                if value is None or (not isinstance(value, (dict, list, tuple)) and pd.isna(value)):
                    ws.write_blank(row_index, col, None, fmt)
                elif isinstance(value, bool):
                    ws.write_boolean(row_index, col, value, fmt)
                elif isinstance(value, Real):
                    if math.isfinite(value):
                        ws.write_number(row_index, col, value, fmt)
                else:
                    value = str(value)
                    ws.write_string(row_index, col, value, fmt)
                    height = max(height, min(120, 16 * (1 + len(value) // 28 + value.count("\n"))))
            ws.set_row(row_index, height)
        ws.freeze_panes(5, 1)
        ws.repeat_rows(0, 4)
        ws.print_area(0, 0, 4 + len(frame), max(5, len(columns) - 1))
        for col, column in enumerate(frame.columns):
            if "profit" in str(column) or "variance" in str(column):
                ws.conditional_format(
                    5, col, 4 + len(frame), col, {"type": "cell", "criteria": "<", "value": 0, "format": negative}
                )
    ws = sheet("Методология" if ru else "Methodology", "Сведения об экспорте" if ru else "Export information")
    ws.set_column(0, 0, 30)
    ws.set_column(1, 5, 24)
    ws.merge_range(
        3,
        0,
        3,
        5,
        "Снимок расчётов, не редактируемая финансовая модель. Прогноз — допущение. Данные и валюта анализов могут отличаться от текущей базы; исходные параметры сохранены ниже."
        if ru
        else "Snapshot of calculated values, not an editable financial model. Forecasts are assumptions. Analyses may use earlier inputs or currencies; provenance is recorded below.",
        note,
    )
    ws.set_row(3, 48)
    row = 5
    for key, value in manifest.items():
        ws.write_string(row, 0, str(key), header)
        serialized = json.dumps(value, ensure_ascii=False, indent=2) if isinstance(value, (dict, list)) else str(value)
        # Keep each source model readable; avoid silently truncating Excel's cell text limit.
        for chunk_start in range(0, max(1, len(serialized)), 30000):
            chunk = serialized[chunk_start : chunk_start + 30000]
            ws.merge_range(row, 1, row, 5, chunk, text)
            ws.set_row(row, min(409, max(30, 14 * (chunk.count("\n") + 1))))
            row += 1
    ws.freeze_panes(5, 1)
    book.close()
    return output.getvalue()
